// Claude's review tests for A37: SSE framing and file validation. agy: do not edit this file.
import { describe, expect, it } from 'vitest';
import { exportProject, parseProjectFile } from './exportFile';
import { parseSseFrame, sseFrame, streamBodyText } from './stream';
import { newProject, type Mock } from './types';

describe('sseFrame', () => {
  it('plain text becomes data: lines, one per line, then a blank line', () => {
    expect(sseFrame('hello')).toBe('data: hello\n\n');
    expect(sseFrame('a\nb')).toBe('data: a\ndata: b\n\n');
  });
  it('a chunk that already has field lines is kept as written', () => {
    expect(sseFrame('event: done\nid: 7\ndata: bye')).toBe('event: done\nid: 7\ndata: bye\n\n');
    expect(sseFrame('retry: 100\ndata: x')).toBe('retry: 100\ndata: x\n\n');
  });
});

describe('parseSseFrame', () => {
  it('reads event, id and the data lines joined', () => {
    expect(parseSseFrame('event: done\nid: 7\ndata: a\ndata: b')).toEqual({ event: 'done', id: '7', data: 'a\nb' });
    expect(parseSseFrame('hello')).toEqual({ event: 'message', id: '', data: 'hello' });
  });
});

describe('streamBodyText', () => {
  it('joins the chunks, framed when sse', () => {
    expect(streamBodyText({ chunks: ['a', 'b'], gapMs: 0, sse: false })).toBe('ab');
    expect(streamBodyText({ chunks: ['a', 'b'], gapMs: 0, sse: true })).toBe('data: a\n\ndata: b\n\n');
  });
});

describe('files carry stream replies', () => {
  function file(stream: unknown): string {
    const p = newProject('p', 'http://a.test');
    const m: Mock = {
      id: 'm', enabled: true, method: 'GET', urlPattern: '/x', source: 'manual', createdAt: 0, reply: 'stream', stream: stream as Mock['stream'],
      response: { status: 200, headers: {}, body: '', bodyEncoding: 'text', delayMs: 0 },
    };
    p.scenarios[0]!.mocks.push(m);
    return exportProject(p);
  }
  it('round-trips, and rejects a bad one', () => {
    const s = { chunks: ['a', 'b'], gapMs: 50, sse: true };
    const r = parseProjectFile(file(s));
    expect(r.ok && r.project.scenarios[0]!.mocks[0]!.stream).toEqual(s);
    expect(parseProjectFile(file({ chunks: 'a', gapMs: 1, sse: false })).ok).toBe(false);
    expect(parseProjectFile(file({ chunks: ['a'], gapMs: -1, sse: false })).ok).toBe(false);
    expect(parseProjectFile(file({ chunks: ['a'], gapMs: 1 })).ok).toBe(false);
  });
});
